// reproduce.js
const lighthouse = require('lighthouse');
const chromeLauncher = require('chrome-launcher');
const fs = require('fs');

async function runLighthouse() {
  // Launch headless Chrome
  const chrome = await chromeLauncher.launch({
    chromeFlags: ['--headless', '--no-sandbox']
  });

  // Lighthouse options: default mobile emulation
  const options = {
    port: chrome.port,
    output: 'html',
    logLevel: 'info',
    formFactor: 'mobile',             // ensure mobile emulation
    screenEmulation: {               // explicit emulation settings
      width: 360,
      height: 640,
      deviceScaleFactor: 3,
      mobile: true
    }
  };

  // Run Lighthouse against a sample page
  const runnerResult = await lighthouse('https://example.com', options);

  // Save the HTML report
  fs.writeFileSync('lighthouse-report.html', runnerResult.report, 'utf-8');
  console.log('✅ Saved report to lighthouse-report.html');

  await chrome.kill();
}

runLighthouse().catch(err => {
  console.error(err);
  process.exit(1);
});
